from gurobipy import *

def solve_problem():
    m = Model("Battlefield_Logistics")
    m.setParam("TimeLimit", 100)  # Set time limit to 100 seconds

    # Data
    depots = list(range(9))  # D0..D8
    units = list(range(10))  # U0..U9
    supplies = list(range(1))  # S0..S0
    days = list(range(2))  # Day0..Day1

    demands = [[[17.51, 36.58]], [[37.64, 49.17]], [[19.85, 41.24]], [[21.61, 13.02]], [[39.71, 19.28]], [[27.46, 43.63]], [[18.35, 31.17]], [[27.91, 47.38]], [[13.6, 34.04]], [[34.54, 43.15]]]
    depot_supplies = [[[38.15, 58.94]], [[42.88, 46.86]], [[39.33, 35.45]], [[41.89, 35.99]], [[27.73, 47.56]], [[35.09, 34.55]], [[35.74, 47.75]], [[35.74, 56.56]], [[38.43, 51.4]]]
    transport_costs = [[4.33, 4.07, 3.67, 3.7, 2.03, 1.71, 2.96, 1.46, 2.15, 3.36], [2.46, 3.54, 4.06, 1.64, 3.36, 1.21, 1.87, 2.84, 3.03, 1.56], [3.32, 3.23, 3.94, 1.95, 3.3, 1.81, 1.33, 3.44, 4.17, 2.26], [3.69, 2.25, 3.1, 1.91, 4.52, 2.75, 2.25, 1.23, 3.81, 1.93], [4.33, 1.65, 1.4, 1.38, 1.39, 4.3, 3.05, 1.92, 2.87, 2.22], [2.27, 3.53, 4.02, 3.95, 3.45, 3.93, 4.24, 4.22, 3.05, 1.62], [4.85, 4.22, 1.25, 2.05, 3.04, 1.56, 1.17, 2.76, 2.72, 2.49], [2.91, 4.19, 3.43, 4.13, 2.31, 1.65, 1.62, 3.51, 2.43, 4.94], [4.35, 4.96, 2.09, 3.92, 1.75, 2.98, 2.11, 1.15, 3.66, 2.69]]
    risk_costs = [[144.19, 111.21, 111.12, 130.69, 54.39, 162.15, 110.39, 59.56, 151.35, 102.64], [86.86, 81.1, 129.69, 167.37, 174.06, 84.83, 198.14, 92.43, 109.25, 110.56], [133.7, 105.47, 150.94, 125.89, 133.5, 64.61, 170.9, 128.54, 90.8, 85.83], [171.26, 101.33, 54.63, 154.0, 164.62, 90.63, 132.46, 183.0, 199.13, 119.49], [60.42, 194.04, 180.27, 159.84, 163.75, 88.56, 93.63, 59.93, 180.14, 106.51], [79.69, 72.97, 86.01, 190.05, 127.93, 104.16, 125.03, 84.36, 62.33, 96.48], [189.29, 111.56, 59.22, 59.66, 87.5, 195.44, 80.33, 181.87, 116.1, 84.14], [179.81, 145.69, 175.08, 184.25, 56.24, 51.75, 132.37, 195.02, 143.54, 120.19], [159.56, 195.75, 57.14, 196.97, 92.53, 160.71, 97.0, 107.98, 174.58, 104.56]]
    supply_volumes = [1.85]
    penalty_costs = [88.41]
    vehicle_cost = 10.0
    vehicle_capacity = 110.0
    total_vehicles = 20

    # Decision variables
    # Flow_D{d}_U{u}_S{s}_Day{t}: Amount of supply s from depot d to unit u on day t
    flows = {}
    for t in days:
        for d in depots:
            for u in units:
                for s in supplies:
                    flows[(d, u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Flow_D{d}_U{u}_S{s}_Day{t}")

    # Slack_U{u}_S{s}_Day{t}: Shortage of supply s at unit u on day t
    slacks = {}
    for t in days:
        for u in units:
            for s in supplies:
                slacks[(u, s, t)] = m.addVar(lb=0.0, vtype=GRB.CONTINUOUS, name=f"Slack_U{u}_S{s}_Day{t}")

    # Veh_D{d}_U{u}_Day{t}: Number of vehicles on route d->u on day t
    vehicles = {}
    for t in days:
        for d in depots:
            for u in units:
                vehicles[(d, u, t)] = m.addVar(lb=0.0, vtype=GRB.INTEGER, name=f"Veh_D{d}_U{u}_Day{t}")

    # Route_D{d}_U{u}_Day{t}: Route d->u is active on day t (binary)
    routes = {}
    for t in days:
        for d in depots:
            for u in units:
                routes[(d, u, t)] = m.addVar(vtype=GRB.BINARY, name=f"Route_D{d}_U{u}_Day{t}")

    # Objective: Minimize total cost (transport + penalty + vehicle + risk)
    obj = quicksum(
        transport_costs[d][u] * flows[(d, u, s, t)]
        for t in days for d in depots for u in units for s in supplies
    )
    obj += quicksum(
        penalty_costs[s] * slacks[(u, s, t)]
        for t in days for u in units for s in supplies
    )
    obj += quicksum(
        vehicle_cost * vehicles[(d, u, t)]
        for t in days for d in depots for u in units
    )
    obj += quicksum(
        risk_costs[d][u] * routes[(d, u, t)]
        for t in days for d in depots for u in units
    )
    m.setObjective(obj, GRB.MINIMIZE)

    # Depot capacity constraints: Total outflow <= supply
    for t in days:
        for d in depots:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for u in units) <= depot_supplies[d][s][t],
                    name=f"DepotCap_D{d}_S{s}_Day{t}"
                )

    # Demand constraints: Inflow + slack >= demand
    for t in days:
        for u in units:
            for s in supplies:
                m.addConstr(
                    quicksum(flows[(d, u, s, t)] for d in depots) + slacks[(u, s, t)] >= demands[u][s][t],
                    name=f"Demand_U{u}_S{s}_Day{t}"
                )

    # Vehicle capacity constraints: Total volume <= vehicles * capacity
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    quicksum(supply_volumes[s] * flows[(d, u, s, t)] for s in supplies) <= vehicle_capacity * vehicles[(d, u, t)],
                    name=f"VehCap_D{d}_U{u}_Day{t}"
                )

    # Route activation constraints: vehicles <= total_vehicles * route
    for t in days:
        for d in depots:
            for u in units:
                m.addConstr(
                    vehicles[(d, u, t)] <= total_vehicles * routes[(d, u, t)],
                    name=f"RouteAct_D{d}_U{u}_Day{t}"
                )

    # Fleet size constraints: Total vehicles <= total_vehicles
    for t in days:
        m.addConstr(
            quicksum(vehicles[(d, u, t)] for d in depots for u in units) <= total_vehicles,
            name=f"FleetSize_Day{t}"
        )

    m.optimize()
    return m
